var VC={C:['C3','G3','C4','E4'],G:['G2','D3','G3','B3'],Am:['A2','E3','A3','C4'],F:['F2','C3','F3','A3'],Dm:['D3','A3','D4','F4'],Em:['E3','B3','E4','G4'],G7:['G2','D3','F3','B3'],E:['E2','B2','E3','G#3']};
function sc(r,semis){var m=r.match(/^([A-G]#?)(-?\d)$/);var b=12*(parseInt(m[2],10)+1)+PCS.indexOf(m[1]);return semis.map(function(s){var x=b+s;return PCS[x%12]+(Math.floor(x/12)-1)})}
var SC={major:[0,2,4,5,7,9,11,12],natmin:[0,2,3,5,7,8,10,12],harm:[0,2,3,5,7,8,11,12],mel:[0,2,3,5,7,9,11,12],dor:[0,2,3,5,7,9,10,12],mix:[0,2,4,5,7,9,10,12],lyd:[0,2,4,6,7,9,11,12],phr:[0,1,3,5,7,8,10,12],blues:[0,3,5,6,7,10,12],minpent:[0,3,5,7,10,12]};
/* ---------- Music theory engine: spelling, chords, scales, voicings, roman numerals ---------- */
var LETTERS='CDEFGAB',NATPC=[0,2,4,5,7,9,11];
var FLATN=['C','D♭','D','E♭','E','F','G♭','G','A♭','A','B♭','B'];
function accSym(n){return n===0?'':n>0?'♯♯♯'.slice(0,n):'♭♭♭'.slice(0,-n)}
function mod12(x){return((x%12)+12)%12}
function pcSharp(pc){return PCS[mod12(pc)]}
/* "B♭", "Bb", "F#", "F♯" -> {l,acc,pc,len} */
function parseRoot(s){
  var m=String(s).match(/^([A-G])([#♯b♭]*)/);if(!m)throw new Error('bad root '+s);
  var acc=0;(m[2]||'').split('').forEach(function(c){acc+=(c==='#'||c==='♯')?1:-1});
  var l=LETTERS.indexOf(m[1]);
  return {l:l,acc:acc,pc:mod12(NATPC[l]+acc),len:m[0].length};
}
function spellFrom(root,deg,semis){
  var l=(root.l+deg-1)%7,d=mod12(root.pc+semis-NATPC[l]);if(d>6)d-=12;
  return {name:LETTERS[l]+accSym(d),acc:d};
}
/* double accidentals read badly for learners: respell them with a plain name */
function friendly(list){
  return list.map(function(x){return Math.abs(x.acc)>1?FLATN[mod12(NATPC[LETTERS.indexOf(x.name[0])]+x.acc)]:x.name});
}

var SCALES={
  major:[[1,0],[2,2],[3,4],[4,5],[5,7],[6,9],[7,11]],
  natmin:[[1,0],[2,2],[3,3],[4,5],[5,7],[6,8],[7,10]],
  harmin:[[1,0],[2,2],[3,3],[4,5],[5,7],[6,8],[7,11]],
  melmin:[[1,0],[2,2],[3,3],[4,5],[5,7],[6,9],[7,11]],
  dorian:[[1,0],[2,2],[3,3],[4,5],[5,7],[6,9],[7,10]],
  phrygian:[[1,0],[2,1],[3,3],[4,5],[5,7],[6,8],[7,10]],
  lydian:[[1,0],[2,2],[3,4],[4,6],[5,7],[6,9],[7,11]],
  mixolydian:[[1,0],[2,2],[3,4],[4,5],[5,7],[6,9],[7,10]],
  locrian:[[1,0],[2,1],[3,3],[4,5],[5,6],[6,8],[7,10]],
  altered:[[1,0],[2,1],[3,3],[4,4],[5,6],[6,8],[7,10]],
  lydiandom:[[1,0],[2,2],[3,4],[4,6],[5,7],[6,9],[7,10]],
  majpent:[[1,0],[2,2],[3,4],[5,7],[6,9]],
  minpent:[[1,0],[3,3],[4,5],[5,7],[7,10]],
  blues:[[1,0],[3,3],[4,5],[5,6],[5,7],[7,10]]
};
var SCALE_FA={major:'ماژور',natmin:'مینور طبیعی',harmin:'مینور هارمونیک',melmin:'مینور ملودیک',dorian:'دورین',phrygian:'فریجین',lydian:'لیدین',mixolydian:'میکسولیدین',locrian:'لوکرین',lydiandom:'لیدین دومینانت',altered:'آلتره',majpent:'پنتاتونیک ماژور',minpent:'پنتاتونیک مینور',blues:'بلوز'};
/* scale('G','major') -> {names:[...], pcs:[...], sharp:[...]} */
function scale(rootName,type){
  var r=parseRoot(rootName),defs=SCALES[type];if(!defs)throw new Error('bad scale '+type);
  var sp=defs.map(function(d){return spellFrom(r,d[0],d[1])});
  var pcs=defs.map(function(d){return mod12(r.pc+d[1])});
  return {root:r,names:friendly(sp),pcs:pcs,sharp:pcs.map(pcSharp),semis:defs.map(function(d){return d[1]})};
}
function scaleSeq(rootName,type,oct){
  var s=scale(rootName,type),base=12*((oct==null?4:oct)+1)+s.root.pc;
  return s.semis.map(function(x){return midiName(base+x)}).concat([midiName(base+12)]);
}

var CHORDS={
  '':[[1,0],[3,4],[5,7]],'m':[[1,0],[3,3],[5,7]],'dim':[[1,0],[3,3],[5,6]],'aug':[[1,0],[3,4],[5,8]],
  'sus2':[[1,0],[2,2],[5,7]],'sus4':[[1,0],[4,5],[5,7]],'5':[[1,0],[5,7]],
  '6':[[1,0],[3,4],[5,7],[6,9]],'m6':[[1,0],[3,3],[5,7],[6,9]],
  '7':[[1,0],[3,4],[5,7],[7,10]],'maj7':[[1,0],[3,4],[5,7],[7,11]],'m7':[[1,0],[3,3],[5,7],[7,10]],
  'm7b5':[[1,0],[3,3],[5,6],[7,10]],'dim7':[[1,0],[3,3],[5,6],[7,9]],'7sus4':[[1,0],[4,5],[5,7],[7,10]],
  'add9':[[1,0],[3,4],[5,7],[9,14]],'9':[[1,0],[3,4],[5,7],[7,10],[9,14]],'maj9':[[1,0],[3,4],[5,7],[7,11],[9,14]],
  'm9':[[1,0],[3,3],[5,7],[7,10],[9,14]],'13':[[1,0],[3,4],[5,7],[7,10],[13,21]],
  '7b9':[[1,0],[3,4],[5,7],[7,10],[9,13]],'7#9':[[1,0],[3,4],[5,7],[7,10],[9,15]],'7#5':[[1,0],[3,4],[5,8],[7,10]],
  'mMaj7':[[1,0],[3,3],[5,7],[7,11]],'m11':[[1,0],[3,3],[5,7],[7,10],[9,14],[11,17]],'maj13':[[1,0],[3,4],[5,7],[7,11],[13,21]]
};
var QALIAS={'min':'m','-':'m','M7':'maj7','Δ':'maj7','Δ7':'maj7','°':'dim','°7':'dim7','ø':'m7b5','ø7':'m7b5','+':'aug','m7♭5':'m7b5','7♭9':'7b9','7♯9':'7#9','7♯5':'7#5','m(maj7)':'mMaj7','maj':'', 'M':''};
function normQ(q){q=String(q).replace(/♭/g,'b').replace(/♯/g,'#');return QALIAS[q]!=null?QALIAS[q]:q}
/* chord('Bb7') -> {names:['B♭','D','F','A♭'], pcs:[...], sharp:[...], root:{...}, q:'7'} */
function chord(name){
  var r=parseRoot(name),q=normQ(name.slice(r.len));
  var defs=CHORDS[q];if(!defs)throw new Error('bad chord '+name+' ('+q+')');
  var sp=defs.map(function(d){return spellFrom(r,d[0],d[1])});
  var pcs=defs.map(function(d){return mod12(r.pc+d[1])});
  return {root:r,q:q,names:friendly(sp),pcs:pcs,sharp:pcs.map(pcSharp),semis:defs.map(function(d){return d[1]})};
}
function midiName(m){return PCS[mod12(m)]+(Math.floor(m/12)-1)}
/* playable voicing: bass note, the root again above it, then the other chord tones stacked upward */
function voicing(name){
  var c=chord(name),bass=48+c.root.pc,out=[midiName(bass)];
  c.semis.forEach(function(s){out.push(midiName(bass+12+s))});
  return out;
}
/* text helpers for writing lessons */
function sp(name){return chord(name).names.join(' ')}
function spS(root,type){return scale(root,type).names.join(' ')}

/* roman numerals: rn('D','major','V7') -> 'A7' ; rn('C','major','♭VII') -> 'B♭' ; rn('A','minor','iv') -> 'Dm' */
var ROMAN={I:1,II:2,III:3,IV:4,V:5,VI:6,VII:7};
function rn(keyRoot,mode,numeral){
  var m=String(numeral).replace(/♭/g,'b').replace(/♯/g,'#').match(/^([b#]?)(VII|VI|IV|V|III|II|I|vii|vi|iv|v|iii|ii|i)(.*)$/);
  if(!m)throw new Error('bad numeral '+numeral);
  var r=parseRoot(keyRoot),defs=SCALES[mode==='minor'?'natmin':'major'];
  var up=m[2]===m[2].toUpperCase(),deg=ROMAN[m[2].toUpperCase()],d=defs[deg-1];
  var shift=m[1]==='b'?-1:m[1]==='#'?1:0;
  var s=spellFrom(r,d[0],d[1]+shift),name=friendly([s])[0];
  var ext=m[3]||'',q;
  if(ext==='°'||ext==='dim')q='dim';else if(ext==='°7'||ext==='dim7')q='dim7';else if(ext==='ø'||ext==='ø7'||ext==='m7b5')q='m7b5';
  else if(ext==='7')q=up?'7':'m7';else if(ext==='maj7')q='maj7';else if(ext==='')q=up?'':'m';else q=ext;
  return name+q;
}
function rnProg(keyRoot,mode,list){return list.map(function(x){return rn(keyRoot,mode,x)})}
function voicings(names){return names.map(voicing)}
/* "a few chords to play" helper: turn a chord-name list into spoken text */
function chordsText(list){return list.join(' – ')}

/* compile a loose 'play' description into the shape playEx understands */
function compilePlay(p){
  if(!p)return null;
  if(p.chord&&typeof p.chord==='string')return {chord:voicing(p.chord)};
  if(p.notes)return {chord:p.notes};
  if(p.seq)return {scale:p.seq};
  if(p.scale)return {scale:scaleSeq(p.scale[0],p.scale[1],p.scale[2])};
  if(p.chords)return {prog:voicings(p.chords)};
  if(p.prog&&Array.isArray(p.prog))return {prog:p.prog};
  if(p.prog)return {prog:voicings(rnProg(p.prog.key,p.prog.mode||'major',p.prog.rn))};
  if(p.rhythm)return {rhythm:p.rhythm};
  if(p.note)return {note:p.note};
  if(p.interval)return {interval:p.interval};
  return p;
}

