function mix(o,x){x=x||{};for(var k in x)o[k]=x[k];return o}
/* info card: I(title, [paragraphs], {pill,list,viz,demos,tip}) */
function I(title,body,x){return mix({t:'info',title:title,body:[].concat(body)},x)}
/* multiple choice: Q(question, options, answerIndex, why, {ctx,hint,viz,play,note}) */
function Q(q,o,a,why,x){return mix({t:'mcq',q:q,o:o,a:a,why:why},x)}
/* listening: LS(question, play, options, answerIndex, why, {hint}) */
function LS(q,play,o,a,why,x){return mix({t:'listen',q:q,play:play,o:o,a:a,why:why},x)}
/* build chord / scale / notes */
function BC(q,chordName,why,x){return mix({t:'build',q:q,chord:chordName,why:why},x)}
function BS(q,rootType,why,x){return mix({t:'build',q:q,scale:rootType,why:why},x)}
function BN(q,notes,why,x){return mix({t:'build',q:q,notes:notes,why:why},x)}
/* match: M(question, [[left,right],…]) */
function M(q,p,x){return mix({t:'match',q:q,p:p},x)}
