/* ===== واحد ۵: آکوردهای هر گام ===== */

/* سؤال «در کلید K، آکورد درجهٔ N چیست؟» با جواب محاسبه‌شده */
function RQ(key,mode,num,wrong,extra,hint){
  var ans=rn(key,mode,num),opts=[ans].concat(wrong);
  var q='در کلید **'+key.replace('b','♭')+(mode==='minor'?' مینور':' ماژور')+'**، آکورد درجهٔ **'+num+'** کدام است؟';
  return Q(q,opts,0,key+(mode==='minor'?'m':'')+' → '+num+' = '+ans+'.'+(extra?' '+extra:''),{hint:hint||'اول گام را بنویس. بعد درجه را بشمار.'});
}

