/* ===== واحد ۸: مدولاسیون و بازهماهنگی ===== */

/* هفت آکورد سه‌نتی یک گام ماژور */
function triadsOf(key){return ['I','ii','iii','IV','V','vi','vii°'].map(function(n){return rn(key,'major',n)})}
function commonChords(k1,k2){var b=triadsOf(k2);return triadsOf(k1).filter(function(c){return b.indexOf(c)>=0})}
function degOf(key,ch){var i=triadsOf(key).indexOf(ch);return i<0?null:['I','ii','iii','IV','V','vi','vii°'][i]}
function accCount(key){
  var s=scale(key,'major').names,n=0;
  s.forEach(function(x){if(x.length>1)n+=(x[1]==='♯'?1:-1)});
  return n;
}
function acc(key){var n=accCount(key);return n===0?'بدون ♯ و ♭':n>0?fa(n)+' دیز (♯)':fa(-n)+' بمل (♭)'}

