/* ---------- State ---------- */
var S={xp:0,streak:0,last:'',done:{},inst:'',input:'',pdone:{},miss:{},ver:0};
try{var raw=localStorage.getItem('hw-phase1');if(raw)S=Object.assign(S,JSON.parse(raw))}catch(e){}
if((S.ver||0)<2){S.miss={};S.ver=2}
function save(){try{localStorage.setItem('hw-phase1',JSON.stringify(S))}catch(e){}}
function dstr(d){return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}

/* ---------- Content preparation: answers and audio are derived from the theory engine ---------- */
function uniq(a){return a.filter(function(x,i){return a.indexOf(x)===i})}
function prettyNote(n){return n.replace(/#/g,'♯').replace(/b/g,'♭')}
function prepare(e){
  if(e.t==='build'){
    if(typeof e.chord==='string'){var c=chord(e.chord);e.ans=uniq(c.sharp);e.spelled=c.names;e.audio={chord:voicing(e.chord)};delete e.chord}
    else if(e.scale){var s=scale(e.scale[0],e.scale[1]);e.ans=uniq(s.sharp);e.spelled=s.names;e.audio={scale:scaleSeq(e.scale[0],e.scale[1])};delete e.scale}
    else if(e.notes){e.ans=uniq(e.notes.map(function(n){return pcSharp(parseRoot(n).pc)}));e.spelled=e.notes.map(prettyNote)}
  }
  if(e.play){var p=compilePlay(e.play);for(var k in p)e[k]=p[k]}
  if(e.demos)e.demos.forEach(function(d){d.a=compilePlay(d.play)});
}
ALL.forEach(function(L){L.ex.forEach(prepare)});

/* ---------- Audio ---------- */
var AC=null;
/* ---------- Real piano: Salamander Grand Piano v3 (Alexander Holm, CC BY 3.0), sampled in minor thirds, hosted by Tone.js ---------- */
var PNO={local:'',started:false,ready:false,bank:{},roots:[],loaded:0,total:0,shared:false,base:'https://tonejs.github.io/audio/salamander/'};
function pnoList(){var l=[['A0',21]],n=['C','Ds','Fs','A'],o,k;for(o=1;o<=7;o++)for(k=0;k<4;k++)l.push([n[k]+o,12*(o+1)+[0,3,6,9][k]]);l.push(['C8',108]);return l}
function pnoLoad(){
  if(PNO.started||!AC)return;PNO.started=true;var l=pnoList();PNO.total=l.length;
  l.forEach(function(x){
    pnoFetch(pnoUrls(x[0])).then(function(buf){
      PNO.bank[x[1]]=buf;PNO.roots.push(x[1]);PNO.loaded++;PNO.ready=PNO.roots.length>=4;pnoShare();
      if(PNO.loaded===PNO.total&&view==='setup')setupScreen();
    }).catch(function(){});
  });
}
/* Source order per note: your own folder (set PNO.local, e.g. 'piano/'), the Tone.js-hosted mp3s, then the original GitHub repo (one mid-velocity FLAC layer, v8) through jsDelivr */
function pnoUrls(n){
  var u=[],repo=n.replace('s','#');
  if(PNO.local)u.push(PNO.local+n+'.mp3');
  u.push(PNO.base+n+'.mp3');
  u.push('https://cdn.jsdelivr.net/gh/sfzinstruments/SalamanderGrandPiano@master/Samples/'+encodeURIComponent(repo)+'v8.flac');
  return u;
}
function pnoFetch(urls){
  return fetch(urls[0]).then(function(r){if(!r.ok)throw 0;return r.arrayBuffer()}).then(function(b){return AC.decodeAudioData(b)}).catch(function(){
    if(urls.length>1)return pnoFetch(urls.slice(1));throw 0;
  });
}
function pnoNearest(m){var best=null,d=1e9;PNO.roots.forEach(function(r){var x=Math.abs(r-m);if(x<d){d=x;best=r}});return best}
function pnoPlay(f,t,dur,vol){
  var a=AC,m=Math.round(69+12*Math.log2(f/440)),r=pnoNearest(m);if(!a||r===null)return false;
  var s=a.createBufferSource(),g=a.createGain();s.buffer=PNO.bank[r];s.playbackRate.value=Math.pow(2,(m-r)/12);
  var v=Math.min(1,(vol||.12)*2.2),end=t+Math.max(.25,dur);
  g.gain.setValueAtTime(v,t);g.gain.setValueAtTime(v,end);g.gain.exponentialRampToValueAtTime(.001,end+.35);
  s.connect(g);g.connect(a.destination);s.start(t);s.stop(end+.4);return true;
}
function pnoMidi(m,vel){var a=ctx();if(!a)return;var f=440*Math.pow(2,(m-69)/12),v=.04+.12*((vel||80)/127);if(!(PNO.ready&&pnoPlay(f,a.currentTime,1.6,v)))tone(f,a.currentTime,.9,v,'triangle')}
/* the piano workshop has its own synth: hand it the same real samples */
function pnoShare(){
  try{
    var st=(typeof PT!=='undefined'&&PT.state)?PT.state():null;
    if(!st||!st.synth||PNO.roots.length<5)return;
    var syn=st.synth,m=new Map();
    PNO.roots.forEach(function(r){m.set(r,{midi:r,buffer:PNO.bank[r],name:'salamander-'+r})});
    syn.sampleBank=m;syn.sampleLoadReport={loaded:m.size,skipped:0};
    if(!PNO.shared)syn.setSoundMode('samples');PNO.shared=true;
  }catch(e){}
}
function ctx(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();if(AC&&!PNO.started)pnoLoad();return AC}
function freq(n){var m=n.match(/^([A-G]#?)(-?\d)$/);var pc=PCS.indexOf(m[1]);var midi=12*(parseInt(m[2],10)+1)+pc;return 440*Math.pow(2,(midi-69)/12)}
function tone(f,t,dur,vol,type){var a=ctx();if(!a)return;if(!type&&PNO.ready&&f>=26&&f<=4300&&pnoPlay(f,t,dur,vol))return;var o=a.createOscillator(),g=a.createGain();o.type=type||'triangle';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+.015);g.gain.exponentialRampToValueAtTime(.0008,t+dur);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+dur+.05)}
function playChord(notes){var a=ctx();if(!a)return;var t=a.currentTime+.05;notes.forEach(function(n,i){tone(freq(n),t+i*.28,1.1,.16)});var t2=t+notes.length*.28+.35;notes.forEach(function(n,i){tone(freq(n),t2+i*.012,1.8,.14)})}
function stab(notes,t){notes.forEach(function(n){tone(freq(n),t,.28,.11,'sawtooth')})}
function playScale(notes){var a=ctx();if(!a)return;var t=a.currentTime+.05;notes.forEach(function(n,i){tone(freq(n),t+i*.32,.5,.16)})}
function playProg(list){var a=ctx();if(!a)return;var t=a.currentTime+.05;list.forEach(function(ch,k){ch.forEach(function(n,i){tone(freq(n),t+k*1.1+i*.02,1.0,.13)})})}
function drumHit(kind,t,velocity){
  var a=ctx();if(!a)return;var g=a.createGain(),v=velocity||1;
  if(kind==='kick'){
    var o=a.createOscillator();o.type='sine';o.frequency.setValueAtTime(145,t);o.frequency.exponentialRampToValueAtTime(48,t+.13);
    g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.42*v,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.24);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+.26);
  }else{
    var n=Math.floor(a.sampleRate*(kind==='hat'?.045:.16)),b=a.createBuffer(1,n,a.sampleRate),d=b.getChannelData(0);
    for(var i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);
    var src=a.createBufferSource(),filter=a.createBiquadFilter();filter.type='highpass';filter.frequency.value=kind==='hat'?7000:1400;
    src.buffer=b;src.connect(filter);filter.connect(g);g.connect(a.destination);
    g.gain.setValueAtTime(kind==='hat'?.0001:.0001,t);g.gain.exponentialRampToValueAtTime((kind==='hat'?.12:.24)*v,t+.003);g.gain.exponentialRampToValueAtTime(.0001,t+(kind==='hat'?.045:.16));src.start(t);src.stop(t+(kind==='hat'?.05:.17));
  }
}
function playRhythm(p){
  var a=ctx();if(!a)return;
  var step=.25,t=a.currentTime+.1,reps=Math.max(1,Math.ceil(16/p.length));
  for(var r=0;r<reps;r++)p.forEach(function(v,i){
    var at=t+(r*p.length+i)*step;
    if(v===3)drumHit('kick',at,1);
    else if(v===2)drumHit('snare',at,.8);
    else if(v===1)drumHit('hat',at,.7);
    if(r===0) setTimeout(function(){var cells=document.querySelectorAll('.rhythm-cell');cells.forEach(function(c,k){c.classList.toggle('now',k===i)})},Math.max(0,(at-a.currentTime)*1000));
  });
}
function playInterval(iv){var a=ctx();if(!a)return;var t=a.currentTime+.05;tone(freq(iv[0]),t,.7,.16);tone(freq(iv[1]),t+.75,.7,.16);tone(freq(iv[0]),t+1.65,1.5,.14);tone(freq(iv[1]),t+1.65,1.5,.14)}
function renderLessonPianoSvg(startOct,endOct){
  var startMidi=(startOct+1)*12,endMidi=(endOct+2)*12-1;
  var whitePC=[0,2,4,5,7,9,11], noteNames=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
  var whites=0;
  for(var m=startMidi;m<=endMidi;m++)if(whitePC.indexOf(m%12)>=0)whites++;
  var width=whites*26,h='<svg class="keyboard" viewBox="0 0 '+width+' 120" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Piano keyboard">';
  for(var midi=startMidi;midi<=endMidi;midi++){
    var pc=midi%12, octave=Math.floor(midi/12)-1;
    if(whitePC.indexOf(pc)<0)continue;
    var wi=0;for(var m=startMidi;m<midi;m++)if(whitePC.indexOf(m%12)>=0)wi++;
    h+='<g class="key white" data-midi="'+midi+'" data-note="'+noteNames[pc]+octave+'"><rect x="'+(wi*26)+'" y="0" width="26" height="120" rx="3"></rect>'+(pc===0?'<text class="klabel" x="'+(wi*26+13)+'" y="112" text-anchor="middle">C'+octave+'</text>':'')+'</g>';
  }
  for(var midi=startMidi;midi<=endMidi;midi++){
    var pc=midi%12, octave=Math.floor(midi/12)-1;
    if([1,3,6,8,10].indexOf(pc)<0)continue;
    var wi=0;for(var m=startMidi;m<midi;m++)if(whitePC.indexOf(m%12)>=0)wi++;
    var x=wi*26-8;
    h+='<g class="key black" data-midi="'+midi+'" data-note="'+noteNames[pc]+octave+'"><rect x="'+x+'" y="0" width="16" height="74" rx="2"></rect></g>';
  }
  return h+'</svg>';
}
function lessonPianoHtml(){
  return '<div class="lesson-piano"><div class="piano-head"><span class="piano-icon">♫</span><div><h3>نمای زندهٔ کلاویه‌ها</h3><p>هم‌زمان با صدا، نت‌های روشن‌شده را دنبال کن</p></div></div><div class="piano-viewport" id="lessonPianoViewport"><div class="ptkb" id="lessonKeys">'+renderLessonPianoSvg(3,4)+'</div></div><p class="motion-caption" id="lessonKeyCaption">یک اکتاو برای تمرین نمایش داده شده است.</p></div>';
}
var lessonPianoTimers=[];
function animateLessonPiano(e, startAt){
  var box=document.getElementById('lessonKeys');if(!box||!e)return;
  lessonPianoTimers.forEach(clearTimeout);lessonPianoTimers=[];
  var els=Array.prototype.slice.call(box.querySelectorAll('.key'));
  var caption=document.getElementById('lessonKeyCaption');
  els.forEach(function(k){k.classList.remove('active','target')});
  function norm(n){
    if(typeof n!=='string')return '';
    var m=n.match(/^([A-G])([#b]?)(-?\d)$/);if(!m)return '';
    var map={'Cb':'B','Db':'C#','Eb':'D#','Fb':'E','Gb':'F#','Ab':'G#','Bb':'A#','E#':'F','B#':'C'};
    var name=m[1]+m[2],oct=Number(m[3]);
    if(map[name]){name=map[name];if((m[1]==='C'&&m[2]==='b')||(m[1]==='F'&&m[2]==='b'))oct--;}
    return name+oct;
  }
  function valid(n){return !!norm(n)}
  function show(ns,label,index,total){
    var names=ns.map(norm);
    els.forEach(function(k){k.classList.toggle('active',names.indexOf(k.dataset.note)>=0)});
    var first=els.find(function(k){return k.classList.contains('active')});
    if(first){var vp=document.getElementById('lessonPianoViewport');if(vp){var left=first.offsetLeft, right=left+first.offsetWidth;if(left<vp.scrollLeft+16)vp.scrollTo({left:Math.max(0,left-40),behavior:'smooth'});else if(right>vp.scrollLeft+vp.clientWidth-16)vp.scrollTo({left:right-vp.clientWidth+40,behavior:'smooth'});}}
    if(caption)caption.textContent=(label||'اکنون')+' '+ns.join(' + ')+(total>1?' · '+(index+1)+' از '+total:'');
  }
  var audio=e.audio||e, events=[], step=.32;
  if(audio.note&&valid(audio.note))events.push({t:0,notes:[norm(audio.note)],label:'نت'});
  if(audio.interval&&audio.interval.length>=2){
    events.push({t:0,notes:[norm(audio.interval[0])],label:'نت اول'});
    events.push({t:.75,notes:[norm(audio.interval[1])],label:'نت دوم'});
    events.push({t:1.65,notes:audio.interval.map(norm).filter(Boolean),label:'فاصله با هم'});
  }
  if(audio.scale&&audio.scale.length){
    audio.scale.forEach(function(n,i){if(valid(n))events.push({t:i*step,notes:[norm(n)],label:'گام'});});
  }
  if(audio.chord&&audio.chord.length){
    // Chord playback sounds all notes together; light all corresponding keys together.
    var cn=audio.chord.map(norm).filter(Boolean);
    if(cn.length)events.push({t:0,notes:cn,label:'آکورد'});
  }
  if(audio.prog&&audio.prog.length){
    audio.prog.forEach(function(ch,k){
      var ns=Array.isArray(ch)?ch.map(norm).filter(Boolean):[];
      if(ns.length)events.push({t:k*1.1,notes:ns,label:'آکورد '+(k+1)});
    });
  }
  if(!events.length){if(caption)caption.textContent='برای این نمونه، حرکت کلاویه‌ای در دسترس نیست.';return;}
  // Show one octave by default; expand only when this lesson's notes span more octaves.
  var allNotes=[];events.forEach(function(ev){ev.notes.forEach(function(n){var m=String(n).match(/^([A-G])(#?)(-?\d)$/);if(m){var pc={C:0,D:2,E:4,F:5,G:7,A:9,B:11}[m[1]]+(m[2]?1:0);allNotes.push((Number(m[3])+1)*12+pc);}});});
  if(allNotes.length){
    var minMidi=Math.min.apply(null,allNotes),maxMidi=Math.max.apply(null,allNotes);
    var startOct=Math.floor(minMidi/12)-1,endOct=Math.floor(maxMidi/12)-1;
    if(endOct<=startOct)endOct=startOct+1;
    var keyBox=document.getElementById('lessonKeys');
    if(keyBox)keyBox.innerHTML=renderLessonPianoSvg(startOct,endOct);
    els=Array.prototype.slice.call(box.querySelectorAll('.key'));
  }
  events.sort(function(a,b){return a.t-b.t});
  var base=typeof startAt==='number'?startAt:performance.now()+50;
  events.forEach(function(ev,i){
    var delay=Math.max(0,base+ev.t*1000-performance.now());
    lessonPianoTimers.push(setTimeout(function(){show(ev.notes,ev.label,i,events.length)},delay));
  });
}
function playEx(e){
  if(!e)return;
  var clock=ctx(), audioStart=clock?clock.currentTime+.05:null;
  animateLessonPiano(e,performance.now()+50);
  if(e.note){if(clock)tone(freq(e.note),audioStart,1.2,.18);return}
  if(e.interval)return playInterval(e.interval);
  if(e.rhythm)return playRhythm(e.rhythm);
  if(e.scale)return playScale(e.scale);
  if(e.prog)return playProg(e.prog);
  if(e.chord)return playChord(e.chord);
}
function hasAudio(e){return !!(e.note||e.rhythm||e.scale||e.prog||e.interval||(e.chord&&e.chord.length))}
function ding(ok){var a=ctx();if(!a)return;var t=a.currentTime;if(ok){tone(660,t,.2,.12,'sine');tone(880,t+.1,.3,.12,'sine')}else{tone(220,t,.3,.12,'square')}}

/* ---------- Visuals: keyboard, staff, guitar chord box ---------- */
var BKEYS=[['C#','C♯','D♭',0],['D#','D♯','E♭',1],['F#','F♯','G♭',3],['G#','G♯','A♭',4],['A#','A♯','B♭',5]];
function kbHtml(v){
  var hl={},nm={},rootPc=-1;
  function add(pc,name,isRoot){hl[pc]=1;nm[pc]=name;if(isRoot)rootPc=pc}
  if(v.chord){var c=chord(v.chord);c.pcs.forEach(function(pc,i){add(pc,c.names[i],i===0)})}
  else if(v.scale){var s=scale(v.scale[0],v.scale[1]);s.pcs.forEach(function(pc,i){add(pc,s.names[i],i===0)})}
  else if(v.notes){v.notes.forEach(function(n,i){add(parseRoot(n).pc,prettyNote(n),i===0&&v.rootFirst)})}
  if(v.root!=null){var rr=parseRoot(v.root);rootPc=rr.pc;hl[rr.pc]=1;if(!nm[rr.pc])nm[rr.pc]=prettyNote(v.root)}
  var oct=v.oct||1,n=7*oct,w=100/n,i,h='<div class="kbv" aria-hidden="true">';
  for(i=0;i<n;i++){
    var pc=NATPC[i%7],L=LETTERS[i%7],on=hl[pc];
    h+='<span class="wk'+(on?' on':'')+(on&&pc===rootPc?' rt':'')+'">'+(on?nm[pc]:(v.all?L+'<small>'+SOL[L]+'</small>':''))+'</span>';
  }
  for(i=0;i<n;i++){
    var k=i%7;if([0,1,3,4,5].indexOf(k)<0)continue;
    var bp=NATPC[k]+1,bon=hl[bp],bl=BKEYS.filter(function(b){return b[3]===k})[0];
    h+='<span class="bkv'+(bon?' on':'')+(bon&&bp===rootPc?' rt':'')+'" style="left:'+((i+1)*w-w*.3)+'%;width:'+(w*.6)+'%">'+(bon?nm[bp]:(v.all?bl[1]+'<small>'+bl[2]+'</small>':''))+'</span>';
  }
  return h+'</div>';
}
function staffSvg(note,bare){
  var m=note.match(/^([A-G])(#?)(\d)$/),L='CDEFGAB'.indexOf(m[1]);
  var idx=parseInt(m[3],10)*7+L,y=80-(idx-30)*5,x=150,i,ly;
  var s='<div class="'+(bare?'':'card ')+'staffwrap"><svg viewBox="0 0 240 130" role="img" aria-label="نت روی حامل" stroke="currentColor" fill="currentColor">';
  for(i=0;i<5;i++)s+='<line x1="8" x2="232" y1="'+(40+i*10)+'" y2="'+(40+i*10)+'" stroke-width="1.4" opacity=".8"/>';
  s+='<path fill="none" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" d="M22 99C22 106 32 106 32 98C32 80 34 52 37 36C40 20 50 24 47 36C44 48 26 56 22 68C18 82 38 92 43 78C47 64 30 56 26 68C24 76 32 80 36 74"/>';
  for(ly=90;ly<=y+2;ly+=10)s+='<line x1="'+(x-14)+'" x2="'+(x+14)+'" y1="'+ly+'" y2="'+ly+'" stroke-width="1.4"/>';
  for(ly=30;ly>=y-2;ly-=10)s+='<line x1="'+(x-14)+'" x2="'+(x+14)+'" y1="'+ly+'" y2="'+ly+'" stroke-width="1.4"/>';
  s+='<ellipse cx="'+x+'" cy="'+y+'" rx="7.6" ry="5.3" transform="rotate(-20 '+x+' '+y+')" stroke="none"/>';
  s+=y<60?'<line x1="'+(x-7)+'" x2="'+(x-7)+'" y1="'+y+'" y2="'+(y+34)+'" stroke-width="1.8"/>':'<line x1="'+(x+7)+'" x2="'+(x+7)+'" y1="'+y+'" y2="'+(y-34)+'" stroke-width="1.8"/>';
  if(m[2])s+='<path fill="none" stroke-width="1.7" d="M'+(x-26)+' '+(y-9)+'V'+(y+9)+'M'+(x-21)+' '+(y-10)+'V'+(y+8)+'M'+(x-29)+' '+(y-2)+'L'+(x-18)+' '+(y-5)+'M'+(x-29)+' '+(y+5)+'L'+(x-18)+' '+(y+2)+'"/>';
  return s+'</svg></div>';
}
/* guitar chord box: shape is "x32010" (low E first) or an array of frets, -1 = muted */
function boxHtml(shape,name){
  var f=Array.isArray(shape)?shape:shape.split('').map(function(c){return c==='x'?-1:+c});
  var pos=f.filter(function(x){return x>0}),min=pos.length?Math.min.apply(null,pos):1,max=pos.length?Math.max.apply(null,pos):1;
  var base=max<=4?1:min,sx=function(i){return 18+i*13},sy=function(r){return 30+r*17},i,s;
  s='<figure class="cbox"><svg viewBox="0 0 100 112" role="img" aria-label="شکل آکورد '+(name||'')+'" stroke="currentColor" fill="none">';
  for(i=0;i<6;i++)s+='<line x1="'+sx(i)+'" x2="'+sx(i)+'" y1="'+sy(0)+'" y2="'+sy(4)+'" stroke-width="1.2" opacity=".75"/>';
  for(i=0;i<=4;i++)s+='<line x1="'+sx(0)+'" x2="'+sx(5)+'" y1="'+sy(i)+'" y2="'+sy(i)+'" stroke-width="'+(i===0&&base===1?3.2:1.2)+'" opacity="'+(i===0&&base===1?1:.75)+'"/>';
  if(base>1)s+='<text x="3" y="'+(sy(0)+12)+'" font-size="10" fill="currentColor" stroke="none" style="font-family:var(--mono)">'+base+'fr</text>';
  var rows=pos.length?f.map(function(x,k){return x===min?k:-1}).filter(function(k){return k>=0}):[];
  if(min>0&&rows.length>=3){var lo=rows[0],hi=rows[rows.length-1],ok=true;for(i=lo;i<=hi;i++)if(f[i]<min)ok=false;if(ok)s+='<rect x="'+(sx(lo)-5)+'" y="'+(sy(min-base)+4.5)+'" width="'+(sx(hi)-sx(lo)+10)+'" height="8" rx="4" fill="var(--accent)" stroke="none"/>'}
  f.forEach(function(x,k){
    if(x<0)s+='<text x="'+sx(k)+'" y="21" font-size="11" text-anchor="middle" fill="currentColor" stroke="none">×</text>';
    else if(x===0)s+='<circle cx="'+sx(k)+'" cy="18" r="4" stroke-width="1.4"/>';
    else s+='<circle cx="'+sx(k)+'" cy="'+(sy(x-base)+8.5)+'" r="5.4" fill="var(--accent)" stroke="none"/>';
  });
  return s+'</svg>'+(name?'<figcaption>'+fmt('[['+name+']]')+' <small>'+(Array.isArray(shape)?'':shape)+'</small></figcaption>':'')+'</figure>';
}
function vizHtml(v){
  if(!v)return '';
  return [].concat(v).map(function(x){
    if(x.kb)return '<div class="viz">'+kbHtml(x.kb)+(x.cap?'<p class="cap">'+fmt(x.cap)+'</p>':'')+'</div>';
    if(x.staff)return '<div class="viz">'+staffSvg(x.staff,true)+(x.cap?'<p class="cap">'+fmt(x.cap)+'</p>':'')+'</div>';
    if(x.boxes)return '<div class="boxes">'+x.boxes.map(function(b){return boxHtml(b.shape,b.name)}).join('')+'</div>';
    return '';
  }).join('');
}
function paras(arr){return (arr||[]).map(function(s){return /^\s*</.test(s)?s:'<p>'+s+'</p>'}).join('')}
function demosHtml(e){
  if(!e.demos||!e.demos.length)return '';
  return '<div class="demos">'+e.demos.map(function(d,i){return '<button class="demo" data-act="demo" data-i="'+i+'">▶ '+fmt(d.l)+'</button>'}).join('')+'</div>';
}

