function pracHeard(ev){
  var e=cur(),p=pracOf(e.pid),t=pracTargets(p);if(!t||S.input!=='play')return;
  var pc=PCS[mod12(ev.midi)],m=$('#ptg-m');
  if(ev.src!=='midi'&&Math.abs(ev.cents)>35){if(m)m.textContent='نت '+noteLabel(ev.midi)+' نزدیک است ولی '+(ev.cents>0?'کمی بالاست':'کمی پایین است')+'.';return}
  run.pheard=run.pheard||[];
  var hit=t.filter(function(o){return o.pc===pc})[0];
  if(!hit){if(m)m.textContent='نت '+noteLabel(ev.midi)+' را شنیدم؛ جزو نت‌های هدف نیست.';return}
  if(run.pheard.indexOf(pc)<0)run.pheard.push(pc);
  var el=Array.prototype.filter.call(document.querySelectorAll('.ptg-c'),function(x){return x.getAttribute('data-pc')===pc})[0];if(el)el.classList.add('on');
  var all=t.every(function(o){return run.pheard.indexOf(o.pc)>=0});
  if(m)m.textContent=all?'✓ همهٔ نت‌های هدف را شنیدم. آفرین!':'✓ '+hit.l+' درست بود.';
  if(all){var ck=document.querySelector('.ptg');if(ck)ck.classList.add('done')}
}
